const axios = require('axios');

async function search(q) {
  try {
    const res = await axios.get('https://bizno.net/?query=' + encodeURIComponent(q), {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36'
      }
    });
    console.log('Query:', q, 'Status:', res.status, 'Length:', res.data.length);
    const regex = /<a\s+href="\/article\/([^"]+)"[^>]*>([\s\S]*?)<\/a>/g;
    let match;
    let found = 0;
    while ((match = regex.exec(res.data)) !== null) {
      console.log('Found:', match[1], match[2].replace(/<[^>]+>/g, '').trim());
      found++;
    }
    if (found === 0) {
      console.log('No articles found');
    }
  } catch (e) {
    console.error('Error:', e.message);
  }
}

async function run() {
  await search('무몽크');
  await search('허현웅');
}

run();

